]

# Group cells by their difference (r - c) for main diagonals
print("Grouping by r-c (main diagonals):")
diff_groups = {}
for r in range(14):
    for c in range(15):
        if input_grid[r][c] == 9:
            diff = r - c
            if diff not in diff_groups:
                diff_groups[diff] = []
            diff_groups[diff].append((r, c))

for diff in sorted(diff_groups.keys()):
    print(f"d={diff}: {diff_groups[diff]}")

# Also group by sum (r + c) for anti-diagonals
print("\nGrouping by r+c (anti-diagonals):")
sum_groups = {}
for r in range(14):
    for c in range(15):
        if input_grid[r][c] == 9:
            s = r + c
            if s not in sum_groups:
                sum_groups[s] = []
            sum_groups[s].append((r, c))

for s in sorted(sum_groups.keys()):
    print(f"s={s}: {sum_groups[s]}")

# Try grouping by mod patterns
print("\n\nMod-3 pattern for row indices where 9s appear:")
rows_with_9 = set(r for r in range(14) for c in range(15) if input_grid[r][c] == 9)
for r in sorted(rows_with_9):
    print(f"  Row {r}: {r % 3}")

